import random

def get_word():
    """Generate a random word from a list of words."""
    words = [
        "python",
        "javascript",
        "kotlin",
        "ruby",
        "swift",
        "go",
        "javascript",  # For testing purposes
    ]
    return random.choice(words).lower()

def play_hangman(word):
    """Play a game of Hangman with the user."""
    secret_word = list(word)
    guessed_letters = set()
    remaining_guesses = 6

    print(f"\nWelcome to Hangman! The word has {len(word)} letters.\n")

    while remaining_guesses > 0:
        print(f"\nYou have {remaining_guesses} guesses left.\n")

        for i, char in enumerate(secret_word):
            if char in guessed_letters:
                print(f"_{char}_", end=" ")
            else:
                print(f"_{char}_", end=" ")
        print()

        guess = input("Guess a letter: ").lower()
        if guess in secret_word:
            guessed_letters.add(guess)
        else:
            remaining_guesses -= 1

    if remaining_guesses == 0:
        print("\nYou lose! The word was '{}'.\n".format(word))
    else:
        print("\nCongratulations! You win!\n")

if __name__ == "__main__":
    word = get_word()
    play_hangman(word)
```

